/// A transcript message, discriminated by `role`.
#[derive(Debug, Clone, PartialEq)]
pub enum AgentMessage {
	User(UserMessage),
	Developer(DeveloperMessage),
	Assistant(AssistantMessage),
	ToolResult(ToolResultMessage),
	BashExecution(BashExecutionMessage),
	PythonExecution(PythonExecutionMessage),
	EvalExecution(EvalExecutionMessage),
	Custom(CustomMessage),
	HookMessage(HookMessage),
	BranchSummary(BranchSummaryMessage),
	CompactionSummary(CompactionSummaryMessage),
	FileMention(FileMentionMessage),
}

impl AgentMessage {
	/// Decodes from JSON, dispatching on `role`.
	pub fn from_value(value: Value) -> Result<Self, serde_json::Error> {
		let decode: fn(Value) -> Result<Self, serde_json::Error> = match value.get("role").and_then(Value::as_str) {
			Some("user") => |value| serde_json::from_value(value).map(Self::User),
			Some("developer") => |value| serde_json::from_value(value).map(Self::Developer),
			Some("assistant") => |value| serde_json::from_value(value).map(Self::Assistant),
			Some("toolResult") => |value| serde_json::from_value(value).map(Self::ToolResult),
			Some("bashExecution") => |value| serde_json::from_value(value).map(Self::BashExecution),
			Some("pythonExecution") => |value| serde_json::from_value(value).map(Self::PythonExecution),
			Some("evalExecution") => |value| serde_json::from_value(value).map(Self::EvalExecution),
			Some("custom") => |value| serde_json::from_value(value).map(Self::Custom),
			Some("hookMessage") => |value| serde_json::from_value(value).map(Self::HookMessage),
			Some("branchSummary") => |value| serde_json::from_value(value).map(Self::BranchSummary),
			Some("compactionSummary") => |value| serde_json::from_value(value).map(Self::CompactionSummary),
			Some("fileMention") => |value| serde_json::from_value(value).map(Self::FileMention),
			other => {
				return Err(serde_json::Error::custom(format!("unknown AgentMessage role {other:?}")));
			}
		};
		decode(value)
	}
}

impl Serialize for AgentMessage {
	fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
		match self {
			Self::User(member) => serialize_tagged(member, &[("role", "user")], serializer),
			Self::Developer(member) => serialize_tagged(member, &[("role", "developer")], serializer),
			Self::Assistant(member) => serialize_tagged(member, &[("role", "assistant")], serializer),
			Self::ToolResult(member) => serialize_tagged(member, &[("role", "toolResult")], serializer),
			Self::BashExecution(member) => serialize_tagged(member, &[("role", "bashExecution")], serializer),
			Self::PythonExecution(member) => serialize_tagged(member, &[("role", "pythonExecution")], serializer),
			Self::EvalExecution(member) => serialize_tagged(member, &[("role", "evalExecution")], serializer),
			Self::Custom(member) => serialize_tagged(member, &[("role", "custom")], serializer),
			Self::HookMessage(member) => serialize_tagged(member, &[("role", "hookMessage")], serializer),
			Self::BranchSummary(member) => serialize_tagged(member, &[("role", "branchSummary")], serializer),
			Self::CompactionSummary(member) => serialize_tagged(member, &[("role", "compactionSummary")], serializer),
			Self::FileMention(member) => serialize_tagged(member, &[("role", "fileMention")], serializer),
		}
	}
}

impl<'de> Deserialize<'de> for AgentMessage {
	fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
		Self::from_value(Value::deserialize(deserializer)?).map_err(D::Error::custom)
	}
}

