#[derive(Debug, Clone, PartialEq)]
pub enum MixtureAnswer {
	Choice(MixtureChoiceAnswer),
	Noul(MixtureNoulAnswer),
	Score(MixtureScoreAnswer),
}

impl MixtureAnswer {
	/// Decodes from JSON, dispatching on `type`.
	pub fn from_value(value: Value) -> Result<Self, serde_json::Error> {
		let decode: fn(Value) -> Result<Self, serde_json::Error> = match value.get("type").and_then(Value::as_str) {
			Some("choice") => |value| serde_json::from_value(value).map(Self::Choice),
			Some("noul") => |value| serde_json::from_value(value).map(Self::Noul),
			Some("score") => |value| serde_json::from_value(value).map(Self::Score),
			other => {
				return Err(serde_json::Error::custom(format!("unknown MixtureAnswer type {other:?}")));
			}
		};
		decode(value)
	}
}

impl Serialize for MixtureAnswer {
	fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
		match self {
			Self::Choice(member) => serialize_tagged(member, &[("type", "choice")], serializer),
			Self::Noul(member) => serialize_tagged(member, &[("type", "noul")], serializer),
			Self::Score(member) => serialize_tagged(member, &[("type", "score")], serializer),
		}
	}
}

impl<'de> Deserialize<'de> for MixtureAnswer {
	fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
		Self::from_value(Value::deserialize(deserializer)?).map_err(D::Error::custom)
	}
}

